CREATE TABLE source_register (source_id TEXT PRIMARY KEY, local_path TEXT NOT NULL UNIQUE, sha256 TEXT NOT NULL, official_url TEXT, license_status TEXT NOT NULL, verification_status TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE document_inventory (document_id TEXT PRIMARY KEY, local_path TEXT NOT NULL UNIQUE, sha256 TEXT NOT NULL, source_id TEXT REFERENCES source_register(source_id), classification TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE project_sample (sample_id TEXT PRIMARY KEY, project_path TEXT NOT NULL UNIQUE, review_status TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE project_document (sample_id TEXT REFERENCES project_sample(sample_id), document_id TEXT REFERENCES document_inventory(document_id), partition TEXT NOT NULL, PRIMARY KEY(sample_id,document_id));
CREATE TABLE data_import_job (job_id TEXT PRIMARY KEY, import_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL, created_at TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE data_import_audit (audit_id TEXT PRIMARY KEY, job_id TEXT REFERENCES data_import_job(job_id), action TEXT NOT NULL, created_at TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE extracted_field (field_id TEXT PRIMARY KEY, document_id TEXT NOT NULL REFERENCES document_inventory(document_id), field_name TEXT NOT NULL, locator TEXT NOT NULL, value TEXT NOT NULL, review_status TEXT NOT NULL, import_job_id TEXT REFERENCES data_import_job(job_id));
CREATE TABLE material_price (record_id TEXT PRIMARY KEY, material_name TEXT NOT NULL, spec_model TEXT NOT NULL, unit TEXT NOT NULL, region TEXT NOT NULL CHECK(region='410100-INNER-4RING'), period TEXT NOT NULL, price_incl_tax NUMERIC(18,2) NOT NULL CHECK(price_incl_tax>=0), price_excl_tax NUMERIC(18,2) NOT NULL CHECK(price_excl_tax>=0), document_id TEXT NOT NULL REFERENCES document_inventory(document_id), sha256 TEXT NOT NULL, source_page INTEGER NOT NULL CHECK(source_page>0), source_row INTEGER NOT NULL CHECK(source_row>0), license_status TEXT NOT NULL, scope_status TEXT NOT NULL, price_type TEXT NOT NULL CHECK(price_type='OFFICIAL_INFORMATION'), raw_payload TEXT NOT NULL, import_job_id TEXT NOT NULL REFERENCES data_import_job(job_id));
CREATE INDEX material_price_lookup ON material_price(period,region,unit);
CREATE INDEX material_price_source ON material_price(document_id);
CREATE TABLE material_price_correction (correction_id TEXT PRIMARY KEY, record_id TEXT NOT NULL REFERENCES material_price(record_id), source_document_id TEXT NOT NULL REFERENCES document_inventory(document_id), sha256 TEXT NOT NULL, source_page INTEGER NOT NULL CHECK(source_page>0), price_incl_tax NUMERIC(18,2) NOT NULL, price_excl_tax NUMERIC(18,2) NOT NULL, payload TEXT NOT NULL, import_job_id TEXT NOT NULL REFERENCES data_import_job(job_id));
CREATE TABLE quota_chapter (chapter_id TEXT PRIMARY KEY, version TEXT NOT NULL, license_status TEXT NOT NULL, payload TEXT NOT NULL);
CREATE TABLE quota_item (item_id TEXT PRIMARY KEY, chapter_id TEXT NOT NULL REFERENCES quota_chapter(chapter_id), license_status TEXT NOT NULL, test_only INTEGER NOT NULL CHECK(test_only IN (0,1)), payload TEXT NOT NULL);
CREATE TABLE quota_resource (resource_id TEXT PRIMARY KEY, item_id TEXT NOT NULL REFERENCES quota_item(item_id), payload TEXT NOT NULL);
CREATE TABLE quota_note (note_id TEXT PRIMARY KEY, item_id TEXT NOT NULL REFERENCES quota_item(item_id), payload TEXT NOT NULL);
CREATE TABLE quota_conversion (conversion_id TEXT PRIMARY KEY, item_id TEXT NOT NULL REFERENCES quota_item(item_id), payload TEXT NOT NULL);
CREATE TABLE fee_rate_matrix (rate_id TEXT PRIMARY KEY, region TEXT NOT NULL, period TEXT NOT NULL, major TEXT NOT NULL, official_source TEXT, review_status TEXT NOT NULL, formal_usable INTEGER NOT NULL CHECK(formal_usable IN (0,1)), noncompetitive INTEGER NOT NULL CHECK(noncompetitive IN (0,1)), payload TEXT NOT NULL);
CREATE TABLE basis_pack (basis_pack_id TEXT PRIMARY KEY, license_status TEXT NOT NULL, formal_usable INTEGER NOT NULL CHECK(formal_usable IN (0,1)), payload TEXT NOT NULL);
